{
  "root": "main",
  "state": {
    "menuItems": [
      { "item": "Pork belly (samgyeopsal)", "portion": "600–700 g", "cost": "KRW 30,000–38,000" },
      { "item": "Marinated beef/pork (non-spicy)", "portion": "300–400 g", "cost": "KRW 22,000–32,000" },
      { "item": "Mushroom + onion + zucchini", "portion": "1 platter", "cost": "KRW 8,000–15,000" },
      { "item": "Lettuce, perilla, garlic, oil", "portion": "2 sets", "cost": "KRW 6,000–10,000" },
      { "item": "Steamed egg or tofu side", "portion": "1 dish", "cost": "KRW 6,000–10,000" },
      { "item": "Doenjang jjigae (mild)", "portion": "1 pot", "cost": "KRW 7,000–12,000" },
      { "item": "Rice", "portion": "4–6 bowls", "cost": "KRW 4,000–8,000" },
      { "item": "Cold noodles (mild)", "portion": "1 bowl", "cost": "KRW 8,000–12,000" }
    ]
  },
  "elements": {
    "main": { "type": "Stack", "props": { "direction": "vertical", "gap": "md", "padding": 16 }, "children": ["title", "summary", "menuTable", "tips", "actions"] },
    "title": { "type": "Text", "props": { "text": "Seoul Korean BBQ Family Dinner Plan", "variant": "h1" }, "children": [] },
    "summary": { "type": "Text", "props": { "text": "A balanced plan for 6 people (1 vegetarian, 1 non-spicy) with a KRW 140,000 budget. Estimated total: KRW 91,000–127,000.", "variant": "body" }, "children": [] },
    "menuTable": { "type": "Table", "props": { "statePath": "/menuItems", "columns": [{ "key": "item", "label": "Item" }, { "key": "portion", "label": "Portion" }, { "key": "cost", "label": "Est. Cost" }], "domain": "generic", "preferredPresentation": "table" }, "children": [] },
    "tips": { "type": "Stack", "props": { "direction": "vertical", "gap": "sm" }, "children": ["tipsTitle", "tipsBody"] },
    "tipsTitle": { "type": "Text", "props": { "text": "Ordering Strategy", "variant": "h2" }, "children": [] },
    "tipsBody": { "type": "Text", "props": { "text": "Keep meat to 2 proteins. Use mushrooms, egg, rice, and stew as the vegetarian base. Request sauces on the side and start with one round to control waste.", "variant": "body" }, "children": [] },
    "actions": { "type": "Stack", "props": { "direction": "horizontal", "gap": "md" }, "children": ["btn1", "btn2"] },
    "btn1": { "type": "Button", "props": { "label": "Korean BBQ menu guide", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.visitseoul.net/en" } } } }, "children": [] },
    "btn2": { "type": "Button", "props": { "label": "Seoul dining tips", "on": { "press": { "action": "openUrl", "params": { "url": "https://english.visitkorea.or.kr/enu/index.kto" } } } }, "children": [] }
  }
}
